// ignore_for_file: avoid_print
// SentinelX - Phase 4.4.1.2 Dart DSP Parity Generator
// Ingests test waveforms generated by Python and computes Mel-spectrograms via AudioPreprocessor.

import 'dart:io';
import 'dart:typed_data';
import 'dart:convert';
import 'package:flutter_test/flutter_test.dart';
import 'package:sentinel_x/core/audio/audio_preprocessor.dart';

void main() {
  test('Compute Dart DSP Mel-Spectrogram Tensors for Parity Verification', () async {
    print('=' * 70);
    print(' SENTINELX — COMPUTING DART DSP MEL-SPECTROGRAM TENSORS ');
    print('=' * 70);

    final parityDir = Directory('test/dsp_parity');
    expect(parityDir.existsSync(), isTrue);

    final manifestFile = File('${parityDir.path}/manifest.json');
    expect(manifestFile.existsSync(), isTrue);

    final manifest = jsonDecode(manifestFile.readAsStringSync()) as Map<String, dynamic>;
    final testCases = (manifest['test_cases'] as List<dynamic>).cast<String>();

    final preprocessor = AudioPreprocessor();
    final dartResults = <String, dynamic>{};

    for (final name in testCases) {
      final wfFile = File('${parityDir.path}/${name}_waveform.bin');
      expect(wfFile.existsSync(), isTrue, reason: 'Waveform file not found for $name');

      final bytes = wfFile.readAsBytesSync();
      final floatList = Float32List.view(bytes.buffer);

      final sw = Stopwatch()..start();
      final output = preprocessor.processAudio(floatList);
      sw.stop();

      expect(output.isValid, isTrue, reason: 'Preprocessing failed: ${output.errorMessage}');

      final dartTensorFile = File('${parityDir.path}/${name}_dart_tensor.bin');
      dartTensorFile.writeAsBytesSync(output.audioTensor.buffer.asUint8List());

      print('[$name]');
      print('  Waveform Samples: ${floatList.length}');
      print('  Dart Tensor Elements: ${output.audioTensor.length} | Latency: ${output.latencyMs.toStringAsFixed(2)} ms');
      print('  Frames Generated: ${output.timeFramesGenerated} | Range: [${output.minDb.toStringAsFixed(2)} dB, ${output.maxDb.toStringAsFixed(2)} dB]');

      dartResults[name] = {
        'latency_ms': output.latencyMs,
        'time_frames_generated': output.timeFramesGenerated,
        'min_db': output.minDb,
        'max_db': output.maxDb,
        'mean_db': output.meanDb,
        'is_valid': output.isValid,
      };
    }

    final dartManifestFile = File('${parityDir.path}/dart_results.json');
    dartManifestFile.writeAsStringSync(const JsonEncoder.withIndent('  ').convert(dartResults));
    print('\n[Dart Results] Saved to ${dartManifestFile.path}');
  });
}
